import{_ as o,o as c,c as r,j as d,a,G as i,aa as n,B as s}from"./chunks/framework.VLjJFeoF.js";const b=JSON.parse('{"title":"linux常用命令速查表","description":"","frontmatter":{},"headers":[],"relativePath":"docs/devops/linux/useful.md","filePath":"docs/devops/linux/useful.md","lastUpdated":1769531044000}'),l={name:"docs/devops/linux/useful.md"};function h(p,t,m,g,u,f){const e=s("ArticleMetadata");return c(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1769531044000"},[t[0]||(t[0]=d("h1",{id:"linux常用命令速查表",tabindex:"-1"},[a("linux常用命令速查表 "),d("a",{class:"header-anchor",href:"#linux常用命令速查表","aria-label":'Permalink to "linux常用命令速查表"'},"​")],-1)),i(e,{article:{}}),t[1]||(t[1]=n('<h2 id="linux常用命令清单" tabindex="-1">Linux常用命令清单 <a class="header-anchor" href="#linux常用命令清单" aria-label="Permalink to &quot;Linux常用命令清单&quot;">​</a></h2><h3 id="一、文件与目录操作-file-directory-management" tabindex="-1"><strong>一、文件与目录操作 (File &amp; Directory Management)</strong> <a class="header-anchor" href="#一、文件与目录操作-file-directory-management" aria-label="Permalink to &quot;**一、文件与目录操作 (File &amp; Directory Management)**&quot;">​</a></h3><p>日常使用中最频繁的一类命令</p><table tabindex="0"><thead><tr><th>命令</th><th>功能描述</th><th>常用示例</th></tr></thead><tbody><tr><td><code>ls</code></td><td>列出目录内容 (list)。</td><td><code>ls</code> (列出当前目录), <code>ls -l</code> (长格式), <code>ls -a</code> (显示隐藏文件)</td></tr><tr><td><code>cd</code></td><td>切换目录 (change directory)。</td><td><code>cd /home/user</code>, <code>cd ..</code> (返回上一级), <code>cd ~</code> (返回家目录)</td></tr><tr><td><code>pwd</code></td><td>显示当前工作目录的路径 (print working directory)。</td><td><code>pwd</code></td></tr><tr><td><code>mkdir</code></td><td>创建新目录 (make directory)。</td><td><code>mkdir my_project</code>, <code>mkdir -p a/b/c</code> (递归创建)</td></tr><tr><td><code>rmdir</code></td><td>删除空目录 (remove directory)。</td><td><code>rmdir empty_folder</code></td></tr><tr><td><code>touch</code></td><td>创建空文件或更新文件时间戳。</td><td><code>touch new_file.txt</code></td></tr><tr><td><code>cp</code></td><td>复制文件或目录 (copy)。</td><td><code>cp source.txt dest.txt</code>, <code>cp -r source_dir/ dest_dir/</code></td></tr><tr><td><code>mv</code></td><td>移动或重命名文件/目录 (move)。</td><td><code>mv old.txt new.txt</code> (重命名), <code>mv file.txt /tmp/</code> (移动)</td></tr><tr><td><code>rm</code></td><td>删除文件或目录 (remove)。</td><td><code>rm file.txt</code>, <code>rm -r directory/</code> (递归删除), <code>rm -rf dir/</code> (**慎用！**强制删除)</td></tr><tr><td><code>find</code></td><td>在文件系统中查找文件。</td><td><code>find . -name &quot;*.py&quot;</code> (查找当前目录下的py文件)</td></tr></tbody></table><h3 id="二、文本文件查看与处理-viewing-processing-text-files" tabindex="-1"><strong>二、文本文件查看与处理 (Viewing &amp; Processing Text Files)</strong> <a class="header-anchor" href="#二、文本文件查看与处理-viewing-processing-text-files" aria-label="Permalink to &quot;**二、文本文件查看与处理 (Viewing &amp; Processing Text Files)**&quot;">​</a></h3><p>在Linux中，一切皆文件。</p><table tabindex="0"><thead><tr><th>命令</th><th>功能描述</th><th>常用示例</th></tr></thead><tbody><tr><td><code>cat</code></td><td>查看整个文件内容 (concatenate)。</td><td><code>cat file.txt</code></td></tr><tr><td><code>less</code></td><td>分页查看文件内容，功能比<code>more</code>强大。</td><td><code>less large_file.log</code> (可用方向键滚动, <code>q</code>退出)</td></tr><tr><td><code>head</code></td><td>查看文件的前几行。</td><td><code>head -n 20 file.txt</code> (查看前20行)</td></tr><tr><td><code>tail</code></td><td>查看文件的后几行。</td><td><code>tail -n 20 file.txt</code> (查看后20行), <code>tail -f app.log</code> (实时监控)</td></tr><tr><td><code>grep</code></td><td>在文本中搜索匹配的行 (global regular expression print)。</td><td><code>grep &quot;error&quot; log.txt</code>, <code>cat file.txt | grep &quot;keyword&quot;</code></td></tr><tr><td><code>wc</code></td><td>统计文件的行数、单词数、字符数 (word count)。</td><td><code>wc -l file.txt</code> (只统计行数)</td></tr><tr><td><code>diff</code></td><td>比较两个文件的差异。</td><td><code>diff file1.txt file2.txt</code></td></tr></tbody></table><h3 id="三、系统信息与监控-system-information-monitoring" tabindex="-1"><strong>三、系统信息与监控 (System Information &amp; Monitoring)</strong> <a class="header-anchor" href="#三、系统信息与监控-system-information-monitoring" aria-label="Permalink to &quot;**三、系统信息与监控 (System Information &amp; Monitoring)**&quot;">​</a></h3><p>故障排查和性能优化须知。</p><table tabindex="0"><thead><tr><th>命令</th><th>功能描述</th><th>常用示例</th></tr></thead><tbody><tr><td><code>top</code> / <code>htop</code></td><td>实时显示系统进程和资源占用情况。</td><td><code>top</code> (<code>htop</code>是<code>top</code>的彩色增强版，需安装)</td></tr><tr><td><code>ps</code></td><td>显示当前进程的快照 (process status)。</td><td><code>ps aux</code> (显示所有进程), <code>ps -ef | grep &quot;nginx&quot;</code></td></tr><tr><td><code>kill</code></td><td>终止进程。</td><td><code>kill 12345</code> (终止PID为12345的进程), <code>kill -9 12345</code> (强制终止)</td></tr><tr><td><code>df</code></td><td>查看磁盘空间使用情况 (disk free)。</td><td><code>df -h</code> (以人类可读格式显示)</td></tr><tr><td><code>du</code></td><td>查看文件或目录的磁盘占用大小 (disk usage)。</td><td><code>du -sh /path/to/dir</code> (查看目录总大小)</td></tr><tr><td><code>free</code></td><td>查看内存使用情况。</td><td><code>free -h</code></td></tr><tr><td><code>uname</code></td><td>显示系统内核信息。</td><td><code>uname -a</code> (显示所有信息)</td></tr><tr><td><code>ifconfig</code> / <code>ip a</code></td><td>查看和配置网络接口。</td><td><code>ip a</code> (新系统推荐)</td></tr><tr><td><code>ping</code></td><td>测试网络连通性。</td><td><code>ping google.com</code></td></tr></tbody></table><h3 id="四、用户与权限管理-user-permission-management" tabindex="-1"><strong>四、用户与权限管理 (User &amp; Permission Management)</strong> <a class="header-anchor" href="#四、用户与权限管理-user-permission-management" aria-label="Permalink to &quot;**四、用户与权限管理 (User &amp; Permission Management)**&quot;">​</a></h3><p>多用户系统的权限管理须知。</p><table tabindex="0"><thead><tr><th>命令</th><th>功能描述</th><th>常用示例</th></tr></thead><tbody><tr><td><code>sudo</code></td><td>以超级用户（root）权限执行命令。</td><td><code>sudo apt-get update</code></td></tr><tr><td><code>su</code></td><td>切换用户。</td><td><code>su - username</code></td></tr><tr><td><code>chmod</code></td><td>修改文件或目录的权限 (change mode)。</td><td><code>chmod +x script.sh</code> (增加执行权限), <code>chmod 755 file</code></td></tr><tr><td><code>chown</code></td><td>修改文件或目录的所有者 (change owner)。</td><td><code>sudo chown user:group file</code></td></tr><tr><td><code>whoami</code></td><td>显示当前登录的用户名。</td><td><code>whoami</code></td></tr><tr><td><code>passwd</code></td><td>修改用户密码。</td><td><code>passwd</code></td></tr></tbody></table><h3 id="五、软件安装与管理-software-installation-management" tabindex="-1"><strong>五、软件安装与管理 (Software Installation &amp; Management)</strong> <a class="header-anchor" href="#五、软件安装与管理-software-installation-management" aria-label="Permalink to &quot;**五、软件安装与管理 (Software Installation &amp; Management)**&quot;">​</a></h3><p>不同的Linux发行版使用不同的包管理器。</p><table tabindex="0"><thead><tr><th>命令 (Debian/Ubuntu)</th><th>命令 (CentOS/RHEL/Fedora)</th><th>功能描述</th></tr></thead><tbody><tr><td><code>apt-get update</code></td><td><code>yum check-update</code></td><td>更新软件包列表</td></tr><tr><td><code>apt-get upgrade</code></td><td><code>yum upgrade</code></td><td>升级所有已安装的包</td></tr><tr><td><code>apt-get install &lt;pkg&gt;</code></td><td><code>yum install &lt;pkg&gt;</code></td><td>安装一个新软件包</td></tr><tr><td><code>apt-get remove &lt;pkg&gt;</code></td><td><code>yum remove &lt;pkg&gt;</code></td><td>卸载一个软件包</td></tr><tr><td><code>apt-cache search &lt;kw&gt;</code></td><td><code>yum search &lt;kw&gt;</code></td><td>搜索软件包</td></tr></tbody></table><h3 id="六、压缩与解压-archiving-compression" tabindex="-1"><strong>六、压缩与解压 (Archiving &amp; Compression)</strong> <a class="header-anchor" href="#六、压缩与解压-archiving-compression" aria-label="Permalink to &quot;**六、压缩与解压 (Archiving &amp; Compression)**&quot;">​</a></h3><p>传输和备份文件须知。</p><table tabindex="0"><thead><tr><th>命令</th><th>功能描述</th><th>常用示例</th></tr></thead><tbody><tr><td><code>tar</code></td><td>打包和解包文件 (tape archive)。</td><td><code>tar -czvf archive.tar.gz dir/</code> (打包压缩), <code>tar -xzvf archive.tar.gz</code> (解压)</td></tr><tr><td><code>zip</code> / <code>unzip</code></td><td>创建和解压.zip文件。</td><td><code>zip -r archive.zip dir/</code>, <code>unzip archive.zip</code></td></tr><tr><td><code>gzip</code> / <code>gunzip</code></td><td>压缩和解压.gz文件。</td><td><code>gzip file.txt</code> (生成file.txt.gz), <code>gunzip file.txt.gz</code></td></tr></tbody></table>',19))])}const y=o(l,[["render",h]]);export{b as __pageData,y as default};
